-- Action_Plan.md C4 (migration 20261015220000_limits_enforced.sql): the database enforces a
-- platform's limits at the send step. Part A runs the same 50 cases as tests/limits-parity.test.mjs
-- through work_copy_issues and compares with what the TypeScript rule says (the expected column is
-- generated by tests/limits-sql-values.mjs). Part B drives work_schedule, work_publish and
-- work_due_run with real rows. One transaction, rolled back at the end. Result: qa/limits-rules.json.
begin;
create temp table s0 as select last_value, is_called from public.work_no_seq;
create temp table r(n serial, k text, v text, expect text);
create temp table v(k text primary key, val text);
grant all on r, v to authenticated; grant usage on sequence r_n_seq to authenticated;
create temp table acc(p text primary key, a jsonb);
insert into acc values
('instagram', '{"max_chars": 2200, "max_hashtags": 30, "max_media": 10, "fold_chars": 125, "video_only": false}'::jsonb),
('x', '{"max_chars": 280, "max_images": 4, "max_videos": 1, "url_chars": 23, "video_only": false}'::jsonb),
('linkedin', '{"max_chars": 3000, "video_only": false}'::jsonb),
('youtube', '{"max_videos": 1, "title_max": 100, "description_max_bytes": 5000, "video_only": true}'::jsonb),
('tiktok', '{"max_chars": 2200, "max_videos": 1, "max_video_seconds": 600, "video_only": true}'::jsonb),
('facebook', '{"video_only": false}'::jsonb),
('mail', '{"video_only": false}'::jsonb);

-- Part A: the pure rule, case by case ---------------------------------------------------------------
insert into r(k, v, expect)
select 'A' || lpad(c.n::text, 2, '0') || ' ' || c.p,
       array_to_string(array(select x from unnest(public.work_copy_issues(c.t, c.im, c.vi, c.tv, acc.a)) x order by x), ','),
       c.expect
from (values
(1, E'', 0, 0, false, 'instagram', 'EMPTY'),
(2, E'   \n\t ', 0, 0, false, 'instagram', 'EMPTY'),
(3, E'   ', 1, 0, false, 'instagram', ''),
(4, E'نص قصير', 0, 0, false, 'instagram', ''),
(5, repeat(E'ن', 2200), 0, 0, false, 'instagram', ''),
(6, repeat(E'ن', 2201), 0, 0, false, 'instagram', 'TOO_LONG'),
(7, E'#وسم0' || E' #وسم1' || E' #وسم2' || E' #وسم3' || E' #وسم4' || E' #وسم5' || E' #وسم6' || E' #وسم7' || E' #وسم8' || E' #وسم9' || E' #وسم10' || E' #وسم11' || E' #وسم12' || E' #وسم13' || E' #وسم14' || E' #وسم15' || E' #وسم16' || E' #وسم17' || E' #وسم18' || E' #وسم19' || E' #وسم20' || E' #وسم21' || E' #وسم22' || E' #وسم23' || E' #وسم24' || E' #وسم25' || E' #وسم26' || E' #وسم27' || E' #وسم28' || E' #وسم29', 0, 0, false, 'instagram', ''),
(8, E'#وسم0' || E' #وسم1' || E' #وسم2' || E' #وسم3' || E' #وسم4' || E' #وسم5' || E' #وسم6' || E' #وسم7' || E' #وسم8' || E' #وسم9' || E' #وسم10' || E' #وسم11' || E' #وسم12' || E' #وسم13' || E' #وسم14' || E' #وسم15' || E' #وسم16' || E' #وسم17' || E' #وسم18' || E' #وسم19' || E' #وسم20' || E' #وسم21' || E' #وسم22' || E' #وسم23' || E' #وسم24' || E' #وسم25' || E' #وسم26' || E' #وسم27' || E' #وسم28' || E' #وسم29' || E' #وسم30', 0, 0, false, 'instagram', 'TOO_MANY_HASHTAGS'),
(9, E'كلمة #وسم_عربي و#tag و (#أول) وبريد a@b.c#no', 0, 0, false, 'instagram', ''),
(10, E'نص', 10, 0, false, 'instagram', ''),
(11, E'نص', 11, 0, false, 'instagram', 'TOO_MANY_MEDIA'),
(12, E'نص', 6, 5, false, 'instagram', 'TOO_MANY_MEDIA'),
(13, repeat(E'😀', 2200), 0, 0, false, 'instagram', ''),
(14, repeat(E'😀', 2201), 0, 0, false, 'instagram', 'TOO_LONG'),
(15, repeat(E'ن', 280), 0, 0, false, 'x', ''),
(16, repeat(E'ن', 281), 0, 0, false, 'x', 'TOO_LONG'),
(17, E'https://example.org/aaaaaaaaaa' || E' https://example.org/aaaaaaaaaa' || E' https://example.org/aaaaaaaaaa' || E' https://example.org/aaaaaaaaaa' || E' https://example.org/aaaaaaaaaa' || E' https://example.org/aaaaaaaaaa' || E' https://example.org/aaaaaaaaaa' || E' https://example.org/aaaaaaaaaa' || E' https://example.org/aaaaaaaaaa' || E' https://example.org/aaaaaaaaaa' || E' https://example.org/aaaaaaaaaa', 0, 0, false, 'x', ''),
(18, E'https://example.org/aaaaaaaaaa' || E' https://example.org/aaaaaaaaaa' || E' https://example.org/aaaaaaaaaa' || E' https://example.org/aaaaaaaaaa' || E' https://example.org/aaaaaaaaaa' || E' https://example.org/aaaaaaaaaa' || E' https://example.org/aaaaaaaaaa' || E' https://example.org/aaaaaaaaaa' || E' https://example.org/aaaaaaaaaa' || E' https://example.org/aaaaaaaaaa' || E' https://example.org/aaaaaaaaaa' || E' https://example.org/aaaaaaaaaa', 0, 0, false, 'x', 'TOO_LONG'),
(19, repeat(E'ن', 250) || E' ' || E'https://example.', 0, 0, false, 'x', ''),
(20, repeat(E'ن', 260) || E' ' || E'https://example.org/aaaaa', 0, 0, false, 'x', 'TOO_LONG'),
(21, E'نص HTTPS://EXAMPLE.ORG/ABC و http://a.b/c', 0, 0, false, 'x', ''),
(22, E'نص', 4, 0, false, 'x', ''),
(23, E'نص', 5, 0, false, 'x', 'TOO_MANY_IMAGES'),
(24, E'نص', 0, 1, false, 'x', ''),
(25, E'نص', 0, 2, false, 'x', 'TOO_MANY_VIDEOS'),
(26, E'نص', 1, 1, false, 'x', 'MIXED_MEDIA'),
(27, repeat(E'ن', 3000), 0, 0, false, 'linkedin', ''),
(28, repeat(E'ن', 3001), 0, 0, false, 'linkedin', 'TOO_LONG'),
(29, E'عنوان الفيديو', 0, 1, false, 'youtube', ''),
(30, E'عنوان الفيديو', 0, 0, false, 'youtube', 'VIDEO_REQUIRED'),
(31, E'عنوان الفيديو', 0, 0, true, 'youtube', ''),
(32, repeat(E'ن', 100) || E'\nوصف', 0, 1, false, 'youtube', ''),
(33, repeat(E'ن', 101) || E'\nوصف', 0, 1, false, 'youtube', 'TITLE_TOO_LONG'),
(34, E'\nوصف بلا عنوان', 0, 1, false, 'youtube', ''),
(35, E'  \n  \nوصف بعد أسطر فارغة', 0, 1, false, 'youtube', ''),
(36, E'عنوان <b>\nوصف', 0, 1, false, 'youtube', 'TITLE_BRACKETS'),
(37, E'عنوان\nوصف > سهم', 0, 1, false, 'youtube', 'DESCRIPTION_BRACKETS'),
(38, E'عنوان\r\n' || repeat(E'ن', 2500), 0, 1, false, 'youtube', ''),
(39, E'عنوان\r\n' || repeat(E'ن', 2501), 0, 1, false, 'youtube', 'DESCRIPTION_TOO_LONG'),
(40, E'title\n' || repeat(E'a', 5000), 0, 1, false, 'youtube', ''),
(41, E'title\n' || repeat(E'a', 5001), 0, 1, false, 'youtube', 'DESCRIPTION_TOO_LONG'),
(42, E'عنوان', 0, 2, false, 'youtube', 'TOO_MANY_VIDEOS'),
(43, E'وصف تيك توك', 0, 1, false, 'tiktok', ''),
(44, E'وصف تيك توك', 0, 0, false, 'tiktok', 'VIDEO_REQUIRED'),
(45, repeat(E'ن', 2200), 0, 1, false, 'tiktok', ''),
(46, repeat(E'ن', 2201), 0, 1, false, 'tiktok', 'TOO_LONG'),
(47, E'نص فيسبوك طويل ' || repeat(E'ن', 8000), 5, 0, false, 'facebook', ''),
(48, E'', 0, 0, false, 'facebook', 'EMPTY'),
(49, E'', 0, 0, false, 'mail', 'EMPTY'),
(50, E'رسالة', 0, 0, false, 'mail', '')
) as c(n, t, im, vi, tv, p, expect) join acc on acc.p = c.p;


-- Part B: the send step with real rows --------------------------------------------------------------
insert into public.accounts (email, display_name, role, protected) values
 ('dir@t.test','Dir','director',false),('wri@t.test','Wri','writer',false),('pub@t.test','Pub','publisher',false);
insert into auth.users (id, email, email_confirmed_at) values
 ('00000000-0000-0000-0000-00000000d001','dir@t.test',now()),('00000000-0000-0000-0000-00000000b001','wri@t.test',now()),
 ('00000000-0000-0000-0000-00000000c001','pub@t.test',now());
create function pg_temp.who(id text) returns void language sql as $$ select set_config('request.jwt.claims', json_build_object('sub',id,'role','authenticated')::text, true) $$;
create function pg_temp.t(k text, sqltext text, e text) returns void language plpgsql as $$
begin
  begin execute sqltext; insert into r(k,v,expect) values (k,'ok',e);
  exception when others then insert into r(k,v,expect) values (k,'ERR '||sqlerrm,e); end;
end $$;
create function pg_temp.c(k text, val text, e text) returns void language sql as $$ insert into r(k,v,expect) values (k,val,e) $$;
create function pg_temp.g(k text) returns text language sql as $$ select val from v where k = $1 $$;
grant execute on function pg_temp.who(text), pg_temp.t(text,text,text), pg_temp.c(text,text,text), pg_temp.g(text) to authenticated;
set local role authenticated;

select pg_temp.who('00000000-0000-0000-0000-00000000d001');
select pg_temp.t('B01 director adds Instagram', $q$ insert into v select 'ig', public.account_save(null, '{"platform":"instagram","label":"الرسمي","handle":"@t.ig","publishers":["pub@t.test"],"mode":"auto"}')::text $q$, 'ok');
select pg_temp.t('B02 director adds X', $q$ insert into v select 'x', public.account_save(null, '{"platform":"x","label":"الرسمي","handle":"@t_x","publishers":["pub@t.test"],"mode":"auto"}')::text $q$, 'ok');
reset role;

-- Works placed straight in the states the send step starts from.
insert into public.works (id, no, title, type, status, created_by, assignee, due, channels, pub_mode, sched_at) values
 ('CH-9001', 9001, 'نص أطول من حد X', 'post', 'APPROVED', 'wri@t.test', 'wri@t.test', current_date + 5, array[pg_temp.g('ig')::uuid, pg_temp.g('x')::uuid], 'auto', null),
 ('CH-9002', 9002, 'نص أطول من حد إنستغرام', 'post', 'APPROVED', 'wri@t.test', 'wri@t.test', current_date + 5, array[pg_temp.g('ig')::uuid], 'auto', null),
 ('CH-9003', 9003, 'حان موعده والنص أطول', 'post', 'SCHEDULED', 'wri@t.test', 'wri@t.test', current_date + 5, array[pg_temp.g('ig')::uuid], 'auto', now() - interval '1 hour'),
 ('CH-9004', 9004, 'ضمن الحدود', 'post', 'APPROVED', 'wri@t.test', 'wri@t.test', current_date + 5, array[pg_temp.g('ig')::uuid, pg_temp.g('x')::uuid], 'auto', null);
insert into public.work_texts (work_id, n, body, author) values
 ('CH-9001', 1, repeat('ن', 300), 'wri@t.test'),
 ('CH-9002', 1, repeat('ن', 2300), 'wri@t.test'),
 ('CH-9003', 1, repeat('ن', 2300), 'wri@t.test'),
 ('CH-9004', 1, 'نص قصير مناسب', 'wri@t.test');

set local role authenticated;
select pg_temp.who('00000000-0000-0000-0000-00000000c001');
select pg_temp.t('B03 scheduling a copy over the limit of X is refused', $q$ select public.work_schedule('CH-9001', now() + interval '2 days', 'auto') $q$, 'ERR COPY_OVER_LIMIT: x TOO_LONG');
reset role;
select pg_temp.c('B04 and nothing changed', (select status || ' ' || coalesce(sched_at::text, 'null') from public.works where id = 'CH-9001'), 'APPROVED null');
-- A copy of its own for X fixes it: the platform's latest non-blank variant is the one counted.
insert into public.work_variants (work_id, platform, n, body, base, author) values ('CH-9001', 'x', 1, 'نسخة قصيرة لـ X', 1, 'wri@t.test');
set local role authenticated;
select pg_temp.who('00000000-0000-0000-0000-00000000c001');
select pg_temp.t('B05 with a short copy of its own, it is scheduled', $q$ select public.work_schedule('CH-9001', now() + interval '2 days', 'auto') $q$, 'ok');
select pg_temp.t('B06 publishing now a copy over the limit of Instagram is refused', $q$ select public.work_publish('CH-9002', 'now') $q$, 'ERR COPY_OVER_LIMIT: instagram TOO_LONG');
reset role;
select pg_temp.c('B07 and nothing was recorded', (select status || ' ' || results::text from public.works where id = 'CH-9002'), 'APPROVED {}');
set local role authenticated;
select pg_temp.who('00000000-0000-0000-0000-00000000c001');
select pg_temp.t('B08 a work within the limits publishes (simulation)', $q$ select public.work_publish('CH-9004', 'now') $q$, 'ok');
reset role;
select pg_temp.c('B09 and is published on both accounts', (select status from public.works where id = 'CH-9004'), 'PUBLISHED');
set local role authenticated;
select pg_temp.who('00000000-0000-0000-0000-00000000c001');
select pg_temp.t('B10 the due run does not raise', $q$ select public.work_due_run() $q$, 'ok');
reset role;
select pg_temp.c('B11 a due work over its limit fails with the reason', (select status || ' ' || (results -> pg_temp.g('ig') ->> 'why') from public.works where id = 'CH-9003'), 'FAILED النسخة تتجاوز حد المنصة');
set local role authenticated;
select pg_temp.who('00000000-0000-0000-0000-00000000c001');
select pg_temp.t('B12 retry is refused while it is still over the limit', $q$ select public.work_publish('CH-9003', 'retry') $q$, 'ERR COPY_OVER_LIMIT: instagram TOO_LONG');
select pg_temp.t('B13 the helper functions are not callable through the API', $q$ select public.work_copy_issues('x', 0, 0, false, '{}'::jsonb) $q$, 'ERR permission denied for function work_copy_issues');
reset role;
select setval('public.work_no_seq', last_value, is_called) from s0;

select n, k, v, expect from r where v is distinct from expect
union all select 0, 'TOTAL', count(*)::text, (count(*) filter (where v is not distinct from expect))::text || ' passed' from r
order by n;
rollback;
